### LeetCode Username

bramar2

### Problem Number, Title, and Link

3394. Check if Grid can be Cut into Sections https://leetcode.com/problems/check-if-grid-can-be-cut-into-sections/description/

### Bug Category

Missing test case *(Incorrect/Inefficient Code getting accepted because of missing test cases)*

### Bug Description

Submission https://leetcode.com/problems/check-if-grid-can-be-cut-into-sections/submissions/1492209908/.

The code is missing the check if there exists a rectangle in the middle of c1 and c2 but the weak testcases doesn't account for this specific case. It gets AC but WA on the following case:
```
n = 6
rectangles = [[4,0,5,2],[0,5,4,6],[4,5,6,6]]
```
Raw (Source):
```
6
[[4,0,5,2],[0,5,4,6],[4,5,6,6]]
```

### Language Used for Code

C++

### Code used for Submit/Run operation

```cpp
#include <bits/stdc++.h>
using namespace std;
class Solution {
public:
    bool checkValidCuts(int n, vector<vector<int>>& rectangles) {
        auto chk = [&](int p1, int p2) -> bool {
            int c1 = INT_MAX, c2 = INT_MIN;
  			
  			set<pair<int,int>> st;
  			for(auto& rect : rectangles) {
  				st.insert(pair(rect[p1], rect[p2]));
  				c1 = min(c1, rect[p2]);
  			}
  			st.erase(st.begin());
  			while(!st.empty() && st.begin()->first < c1) {
  				c1 = max(c1, st.begin()->second);
  				st.erase(st.begin());
  			}


  			st.clear();
  			for(auto& rect : rectangles) {
  				st.insert(pair(rect[p2], rect[p1]));
  				c2 = max(c2, rect[p1]);
  			}

  			st.erase(st.begin());
  			while(!st.empty() && st.rbegin()->first > c2) {
  				c2 = min(c2, st.rbegin()->second);
  				st.erase(prev(st.end()));
  			}
            // this check is missing for middle section between c1 and c2
            //   but still AC
            /*
            bool valid = c1 < c2;
            bool sq1 = false, sq2 = false, sq3 = false;
            for(auto& rect : rectangles) {
                if(!valid) break;
                if(0 <= rect[p1] && rect[p2] <= c1) {
                    sq1 = true;
                }else if(c1 <= rect[p1] && rect[p2] <= c2) {
                    sq2 = true;
                }else if(c2 <= rect[p1]) {
                    sq3 = true;
                }else {
                    valid = false;
                }
            }
            return valid && sq1 && sq2 && sq3;
            */
            return c1 < c2;
        };
        return chk(0, 2) || chk(1, 3);
    }
};
```


### Expected behavior

It should get WA on submit.

